// Light Parse - Just clean formatting, let AI do the extraction
const slackMessage = $input.first().json;
const text = (slackMessage.text || '').trim();

// Remove @mentions but keep everything else natural
const cleanText = text.replace(/<@[A-Z0-9]+>/g, '').trim();

// Generate correlation ID for tracking
const correlationId = `corr_${Date.now()}_${slackMessage.user}_${Math.random().toString(36).substring(2, 8)}`;

return {
  json: {
    // User's natural language input
    user_message: cleanText,

    // Slack context
    user_id: slackMessage.user,
    channel: slackMessage.channel,
    thread_ts: slackMessage.thread_ts || slackMessage.ts,

    // Tracking
    correlation_id: correlationId,
    timestamp: new Date().toISOString()
  }
};

// Smart Response Formatter - Makes AI output even more natural
const items = $input.all();
const aiOutput = items[0].json.output || items[0].json.text || '';
const parseData = $('Light Parse').first().json;

// If AI already formatted nicely, just pass through
if (typeof aiOutput === 'string' && aiOutput.includes('✅')) {
  return {
    json: {
      text: aiOutput,
      channel: parseData.channel,
      thread_ts: parseData.thread_ts
    }
  };
}

// Otherwise, add some polish
let message = aiOutput;

// Add emoji reactions for different actions
if (message.includes('closed')) message = '✅ ' + message;
else if (message.includes('assigned')) message = '🎯 ' + message;
else if (message.includes('urgent') || message.includes('critical')) message = '🔥 ' + message;
else if (message.includes('found')) message = '🔍 ' + message;

return {
  json: {
    text: message,
    channel: parseData.channel,
    thread_ts: parseData.thread_ts
  }
};
